a=s.index("else if(a.action==='reply'){");b=s.index('else return;refreshPlanMoney()',a)
s=s[:a]+"else if(a.action==='reply'){const p=Game.upgrades.chiringoArchive?.find(p=>p.id===a.id),c=p?.comments?.find(c=>c.id===a.comment);if(!c||c.reply)return;const option=replyOptions(c).find(o=>o.id===a.choice);if(!option||Game.money<option.cost)return;Game.money-=option.cost;c.reply={day:day(),text:option.text,kind:option.id,cost:option.cost};}"+s[b:]
s=s.replace('else return;refreshPlanMoney()',"else return;w.applied=[...(w.applied||[]),a.requestId].slice(-256);refreshPlanMoney()")
s=s.replace("const a={action:b.dataset.manage,id:b.dataset.id,comment:b.dataset.comment||'',day:day()};","const w=Game.upgrades.workforce;const action=b.dataset.manage,id=b.dataset.id,target=action==='hire'?w?.applicants.find(c=>c.id===id)?.role:id;const a={action,id,comment:b.dataset.comment||'',choice:b.dataset.choice||'',day:day(),requestId:crypto.randomUUID(),expectedEmployee:w?.team[target]?.id||'',expectedTraining:w?.team[target]?.training||0};")
start=s.index('export function closePhoto()');end=s.index('\nexport function photoThread',start)
s=s[:start]+"export function closePhoto(){const u=Game.upgrades,id=(u.career?.season||1)+':'+Game.day,r=u.chiringoArchive?.find(r=>r.id===id);if(!r||r.threadClosed)return;r.comments=photoComments(r,{stockOuts:Game.dayStats?.stockOuts,showDay:u.showDia,poll:u.socialPoll});r.metrics=u.socialStats?{...u.socialStats}:null;r.threadClosed=true;}"+s[end:]
