s=s[:start]+r'''export function photoThread(r){const comments=r.comments||[];return '<section class="photo-thread"><h4>Comentarios visibles · '+comments.length+'</h4><p class="muted">Las interacciones estimadas de la publicacion se muestran por separado. Responder aqui no genera seguidores ilimitados.</p>'+comments.map(c=>{const author=c.author||{id:'visitor-'+c.authorId,name:AUTHORS[Number(c.authorId)%AUTHORS.length]||'Visitante'};return '<article><img width="36" height="36" src="'+portrait(author)+'" alt=""><b>'+E(author.name)+'</b><p>'+E(c.text)+'</p>'+(c.reply?'<blockquote><b>'+E(Game.upgrades.kioskName||'El Charco Azul')+'</b><p>'+E(c.reply.text)+'</p></blockquote>':replyOptions(c).map(o=>'<button class="btn sm" data-manage="reply" data-id="'+E(r.id)+'" data-comment="'+E(c.id)+'" data-choice="'+o.id+'">'+E(o.label)+'</button>').join(''))+'</article>';}).join('')+(comments.length?'':'<p>Los comentarios apareceran al cerrar la jornada.</p>')+'</section>';}'''+s[end:]
s+=r'''
export {act as applyManagementAction};
function upgradeWorkforce(w){const u=Game.upgrades;if(!u.professionalSchema){u.managementMigrationBackup={workforce:JSON.parse(JSON.stringify(w)),calendar:u.socialCalendar?{...u.socialCalendar}:null,idle:u.socialIdle};for(const e of Object.values(w.team))if(String(e.id).startsWith('original-'))e.dateUnknown=true;const completed=day()-(u.socialSettledAbs===day()?0:1),posts=(u.chiringoArchive||[]).map(r=>(r.season-1)*30+r.day).filter(d=>d<=completed),lastPost=Math.max(0,...posts);u.socialCalendar=reconcileCalendar(u.socialCalendar||{last:completed,idle:u.socialIdle},completed,lastPost);u.socialIdle=u.socialCalendar.idle;u.professionalSchema=1;netDirty();}w.applicants=w.applicants.map(profile);for(const key of Object.keys(w.team))w.team[key]=profile(w.team[key]);}
setInterval(()=>{if(Net.role==='guest'||Game.mode!=='report'||!Game.dayStats||!Game.upgrades.workforce)return;const w=Game.upgrades.workforce;let changed=false;for(const e of Object.values(w.team)){if(e.lastAuditDay===day())continue;e.lastAuditDay=day();if(Game.staff[e.role])e.worked=(e.worked||0)+1;else e.absences=(e.absences||0)+1;changed=true;}if(changed)netDirty();},400);
export function leaguePanel(p,area,tier,d){const w=weeklyPoints(p.history,d),rows=Rankings.table(p.rivals,area,p.rivals.tiers[area],p.history,p.kioskName,d),own=rows.find(r=>r.id==='player'),t=p.rivals.tiers[area];let h='<section class="mk-card"><h3>Puntos de cada jornada</h3><p>Desempates: clientes atendidos en la semana, valoracion media, resultado operativo y, en ultimo caso, identificador estable.</p>';if(t<2)h+='<p>Diferencia actual respecto al 3.º: '+Math.max(0,rows[2].score-own.score)+' puntos. Es provisional, no una garantia de ascenso.</p>';if(t>0)h+='<p>Diferencia respecto al 7.º (permanencia): '+(own.score-rows[6].score)+' puntos.</p>';h+='<table><thead><tr><th>Jornada</th><th>Servicio</th><th>Nota</th><th>Margen</th><th>Comunidad</th><th>Total</th></tr></thead><tbody>'+w.rows.map(r=>'<tr><td>'+r.day+'</td>'+Object.values(r.parts).map(v=>'<td>'+v.toFixed(1)+'</td>').join('')+'<td>'+r.total+'</td></tr>').join('')+'</tbody></table><p>Total semanal: '+w.total+'. Se redondea el total de cada jornada antes de sumarlo.</p>';const a=p.history.slice(-2);if(a.length===2)h+='<p>Ultima jornada cerrada: '+dailyPoints(a[1]).total+' puntos; cambio respecto a la anterior: '+(dailyPoints(a[1]).total-dailyPoints(a[0]).total)+'.</p>';return h+'</section>';}
'''
p.write_text(s)
